"use strict";
const smsDownloads = [
 {code:'铃声01',app:'music',title:'口袋和弦铃声包',tag:'POLYPHONIC / 和弦铃声',image:'images/posters/ringtone.jpg',copy:'把喜欢的旋律，装进每一次来电。',file:'audio/gran-vals.mp3',aliases:['MUSIC01','PHONE01']},
 {code:'壁纸01',app:'photos',title:'夏日校园壁纸',tag:'COLOR WALLPAPER / 彩屏壁纸',image:'images/memories/campus.jpg',copy:'那条放学路，想每天再看一眼。',file:'images/memories/campus.jpg',aliases:['PHOTO01']},
 {code:'游戏01',app:'snake',title:'经典贪吃蛇',tag:'JAVA GAME / 掌中游戏',image:'images/posters/games.jpg',copy:'方向键准备好，再绕一圈就收手。',file:'javame/demos/snake.jar',aliases:['GAME01']},
 {code:'漫画01',app:'comics',title:'雨停以前 · 漫画',tag:'POCKET COMIC / 原创四页',image:'images/reading/rain-comic.jpg',copy:'一部遗落的手机，找回一段旧友情。',file:'images/reading/rain-comic.jpg',aliases:[]},
 {code:'软件01',app:'calculator',title:'掌上计算器',tag:'JAVA TOOL / 实用软件',image:'images/posters/newsstand.jpg',copy:'上课、买点卡、算零花钱，都用得上。',file:'javame/demos/calculator.jar',aliases:[]},
 {code:'便笺01',app:'notes',title:'随手记',tag:'JAVA NOTES / 口袋便笺',image:'images/memories/night.jpg',copy:'把没说出口的话，先写在手机里。',file:'javame/demos/notes.jar',aliases:[]}
];
let smsView='inbox',smsSelected=0,smsSending=false,deskComicPage=0,deskStory='lost-phone',deskWebsite=null;
const deskStampKeys=['sms','install','comic'];
let deskStamps=[];
try{const p=JSON.parse(localStorage.getItem('olddays-memory-stamps')||'[]');if(Array.isArray(p))deskStamps=[...new Set(p.filter(x=>deskStampKeys.includes(x)))];}catch{}
function unlockDeskStamp(id){if(!deskStampKeys.includes(id)||deskStamps.includes(id))return false;deskStamps.push(id);try{localStorage.setItem('olddays-memory-stamps',JSON.stringify(deskStamps));}catch{}const card=document.querySelector('[data-desk-stamp="'+id+'"]');card?.classList?.add?.('stamp-collected');const label=card?.querySelector?.('small');if(label)label.textContent='已收集 ✓';const count=document.querySelector('[data-desk-stamp-count]');if(count)count.textContent=deskStamps.length+'/3 枚记忆邮票';return true;}
function deskAdventuresMarkup(){return `<section class="desk-adventures"><div class="explore-section-title"><h2>今晚的小愿望</h2><span data-desk-stamp-count>${deskStamps.length}/3 枚记忆邮票</span></div><div>${[['sms','✉','给过去发一条短信','漫画01'],['install','↓','给手机装个小软件','store'],['comic','▣','翻完一篇小漫画','comics']].map(([id,icon,title,target])=>`<button data-desk-stamp="${id}" class="${deskStamps.includes(id)?'stamp-collected':''}" ${id==='sms'?`data-sms-offer="${target}"`:`data-desk-open="${target}"`}><b>${icon}</b><span>${title}<small>${deskStamps.includes(id)?'已收集 ✓':'去完成，留一枚回忆 ›'}</small></span></button>`).join('')}</div></section>`;}
function phoneSurfaceActive(){return current.type==='phone'||current.type==='home'&&deskEntered;}
function smsOfferFor(text){const key=String(text).trim().replace(/包月\s*$/,'').toUpperCase();return smsDownloads.find(o=>o.code.toUpperCase()===key||o.aliases.includes(key));}
function deskOpen(app){if(isTextOnlyPhone()&&app==='snake'){startPhoneSnake();return;}if(app==='sms')smsView='inbox';openPhoneLab(app);if(current.type==='home'&&window.innerWidth<620)document.querySelector('.home-phone-preview')?.scrollIntoView?.({block:'start',behavior:'smooth'});}
function renderWorkbench(){if(deviceCapabilities[phoneState.model]&&phoneState.model!=='twist')return renderPlayerWorkbench();if(isTextOnlyPhone())return renderMonoWorkbench();const communities=communityAvailable(),available=siteCatalog.map(c=>({...c,sites:c.sites.filter(s=>s.since<=Number(year()))})).filter(c=>c.sites.length);return `<section class="explore-workbench"><aside class="explore-library" aria-label="旧日探索入口"><header class="explore-intro"><small>OLDDAYS / ${year()} / 掌上互联网</small><h1>好玩的都在左边，<br>记忆装进手机里。</h1><p>逛旧站、翻漫画、发一条下载短信。<br>点选左边，右边的手机就会打开。</p></header><nav class="explore-jump"><button data-desk-section="apps">应用</button><button data-desk-section="ads">短信下载</button><button data-desk-section="comics">漫画</button><button data-desk-section="community">社区</button><button data-desk-section="sites">旧站大全</button></nav>${walletHudMarkup()}<section id="desk-apps"><div class="explore-section-title"><h2>先打开一个应用</h2><span>无需离开手机</span></div><div class="explore-app-grid">${[['browser','UC','UC 浏览器','orange'],['store','↓','软件下载','green'],['sms','✉','短信','lime'],['qq','QQ','QQ','blue'],['ads','AD','短信广告','pink'],['comics','▣','漫画馆','yellow'],['community','聊','社区客厅','blue'],['games','✣','游戏厅','purple'],['books','书','掌上书房','brown'],['music','♫','掌上音乐','pink'],['videos','▶','动漫影院','blue'],['photos','▧','主题壁纸','green'],['magazines','刊','掌上杂志','brown']].map(([id,icon,name,tone])=>`<button data-desk-open="${id}"><b class="system-icon tone-${tone}">${icon}</b>${id==='sms'?smsBadgeMarkup():''}<span>${name}</span></button>`).join('')}</div></section>${explorationHubMarkup()}${deskAdventuresMarkup()}<section id="desk-ads"><div class="explore-section-title"><h2>杂志最后一页</h2><span>短信下载 / 原创广告</span></div><div class="desk-ad-strip">${smsDownloads.map(o=>`<button class="desk-ad-card" data-sms-offer="${o.code}"><img src="${o.image}" alt="${o.title}原创怀旧配图" loading="lazy"><span><small>${o.tag}</small><b>${o.title}</b><strong class="ad-price">${walletPriceLabel(o)} · 游戏币</strong><em>编辑 ${o.code} → 106XXXX</em></span></button>`).join('')}</div><p class="explore-note">点击广告，在右侧编辑短信；回复里领取下载。本机体验，不发真实短信。</p></section><section id="desk-comics"><div class="explore-section-title"><h2>书包里的漫画和故事</h2><span>本站原创</span></div><button class="desk-comic-feature" data-desk-open="comics"><img src="images/reading/rain-comic.jpg" alt="雨停以前原创漫画四页预览" loading="lazy"><span><small>四页短篇漫画</small><b>雨停以前</b><em>点开，一页一页翻 →</em></span></button><div class="desk-story-links">${kioskReads.filter(r=>!r.comic).map(r=>`<button data-desk-story="${r.id}">${escapeHTML(r.title)} <span>图文 ›</span></button>`).join('')}</div></section><section id="desk-community"><div class="explore-section-title"><h2>那些年，还没下线的人</h2><span>${communities.length} 个社区角落</span></div><div class="desk-community-grid">${communities.map(c=>`<button data-desk-community="${c.id}"><b>${escapeHTML(c.name)}</b><span>${escapeHTML(c.boards.join(' · '))}</span><small>进版面，翻楼层 ›</small></button>`).join('')}</div><p class="explore-note">社区为原创怀旧体验，留言仅保存在本浏览器；旧站存档另有入口。</p></section><section id="desk-sites"><div class="explore-section-title"><h2>旧网址，慢慢逛</h2><span>${available.reduce((n,c)=>n+c.sites.length,0)} 个年代入口</span></div><label class="desk-site-search">⌕ <input data-desk-site-search placeholder="搜网站：新浪、猫扑、游戏…" aria-label="筛选左侧旧网站"></label>${available.map(c=>`<details class="desk-site-group" ${['portal','community','mobile'].includes(c.id)?'open':''}><summary>${escapeHTML(c.title)} <span>${c.sites.length}</span></summary><div>${c.sites.map(s=>`<button data-desk-site="${s.url}" data-site-search="${escapeHTML(s.name+' '+s.url+' '+c.title)}">${escapeHTML(s.name)}<small>${s.url}</small></button>`).join('')}</div></details>`).join('')}<p class="desk-sites-empty" hidden>没有找到这个站点，换个名字试试。</p><p class="explore-note">按所选年份查询真实快照；网络受限时，可查看明确标记的本站重制导航。</p></section></aside><section class="home-phone-preview" aria-label="右侧复古手机"><div class="desk-phone-heading"><span><i></i> 你的手机</span><div><button data-desk-open="home">⌂ 桌面</button><button data-phone-picker>换手机</button></div></div>${renderPhoneLab()}</section></section>`;}
function phoneMagazineShelfMarkup(){const available=kioskAvailable(),real=available.filter(m=>kioskRealCovers[m.id]&&kioskRealCovers[m.id].date<=date);return `<section class="pocket-magazine-shelf"><header><small>POCKET MAGAZINE</small><h2>掌上杂志</h2><p>把报刊亭，装进手机里。</p></header>${real.length?`<h3>翻一张真实旧封面</h3><div class="pocket-real-covers">${real.map(m=>{const c=kioskRealCovers[m.id];return `<button data-phone-magazine="${m.id}"><img src="${c.image}" alt="${escapeHTML(m.name+' '+c.label)}"><b>${escapeHTML(m.name)}</b><small>${escapeHTML(c.label)}</small></button>`;}).join('')}</div>`:''}<button class="pocket-original-reading" data-desk-open="comics"><img src="images/reading/rain-comic.jpg" alt="旧日原创阅读本漫画"><span><small>本站原创阅读本</small><b>雨停以前</b><em>四页漫画，点开就读 ›</em></span></button><h3>杂志导览 · ${year()}</h3><div class="pocket-magazine-guides">${available.map((m,i)=>`<button data-phone-magazine="${m.id}"><div class="magazine-type-cover magazine-ink-${i%4}"><small>${m.kind}</small><b>${escapeHTML(m.name)}</b><span>原刊导览</span></div><span>${escapeHTML(m.name)}</span></button>`).join('')}</div><p class="sms-local-note">真实封面保留期号与出处；文字封面为本站导览，不是历史原刊。原刊阅读遵循权利方权限。</p></section>`;}
function phoneGameShelfMarkup(){return `<section class="phone-game-shelf"><header><small>ONE MORE GAME</small><h2>掌中游戏厅</h2><p>方向键准备好，再来最后一局。</p></header><button class="phone-native-game" data-phone-snake>▦ 原生贪吃蛇 <span>经典按键小游戏 ›</span></button><h3>装进旧手机的游戏</h3>${[...pocketClassicGames,...pocketJavaGames].map((g,i)=>`<button class="phone-game-shelf-row" data-launch-java="${g.id}"><b>${['♜','⚔','✦','▦'][i%4]}</b><span>${g.title}<small>${g.id==='pokemon-crystal'?'GBC 兼容模式':'Java ME · 方向键 / 数字键'}</small></span><em>玩 ›</em></button>`).join('')}<p class="sms-local-note">开源重制与历史存档分别标明，手机键盘在屏幕下方。</p></section>`;}
function phoneAdsMarkup(){return `<section class="sms-ad-book"><header><small>MOBILE DIY / 手机新玩法</small><h2>彩屏时代，个性下载！</h2><p>挑一个喜欢的，发条短信带回手机。</p></header>${smsDownloads.map((o,i)=>`<article class="sms-ad-poster ad-paper-${i%3}"><img src="${o.image}" alt="${o.title}原创配图"><small>${o.tag}</small><h3>${o.title}</h3><p>${o.copy}</p><div class="sms-ad-price">${walletPriceLabel(o)}<small>体验话费 / 游戏币</small></div><div class="sms-ad-code">编辑 <b>${o.code}</b><br>发送到 <strong>106XXXX</strong></div><button data-sms-offer="${o.code}">✉ 单次下载 · ${walletMoney(o.price||0)}元</button>${o.monthly?`<button class="sms-monthly-offer" data-sms-offer="${o.code}包月">订阅包月 · ${walletMoney(o.monthly)}元 / 模拟月</button>`:''}<em>怀旧创作广告 · 本机模拟 · 无费用</em></article>`).join('')}</section>`;}
function deliverPhoneSms(text){const t=String(text||'').trim().slice(0,160);if(!t)return false;const offer=smsOfferFor(t),business=handleDreamnetSms(t);const reply=business||(isTextOnlyPhone()?(offer?'【时光信箱】这部手机只支持文字短信。彩屏下载内容请在彩屏手机上领取。':'【时光信箱】收到你的信息。放学以后，老地方见。'):offer?`【旧日下载站】${offer.title}已准备好。${smsPlanFor(t)==='monthly'?'包月':'单次'}价格${walletMoney(walletPrice(offer,smsPlanFor(t)))}元游戏币；确认领取后才扣费。业务帮助可向通讯录里的店老板打听。`:'【时光信箱】你的短信已收到。试试编辑“铃声01”“壁纸01”“游戏01”或“漫画01”，领取一份掌中礼物。');if(offer?.app==='photos')phoneState.wallpaper='blue';phoneState.sent.push({text:t,reply,stamp:date+' 20:04',claimed:false});phoneState.sent=phoneState.sent.slice(-12);phoneState.draft='';smsView='message';smsSelected=0;savePhone();if(!isTextOnlyPhone())unlockDeskStamp('sms');return true;}
function smsDownloadCard(offer,record){return `<article class="sms-download-card"><img src="${offer.image}" alt="${offer.title}下载配图"><b>${offer.title}</b><small>${record.claimed?'已存入手机 · 桌面可打开':'来自 106XXXX 的本机下载卡'}</small><button ${record.claimed?`data-system-launch="${offer.app}"`:`data-sms-claim="${offer.code}"`}>${record.claimed?'打开应用':dreamnet.purchases[offer.code]&&smsPlanFor(record.text)==='once'?'再次领取 · 不重复扣费':'确认下载 · '+walletMoney(walletPrice(offer,smsPlanFor(record.text)))+'元'+(smsPlanFor(record.text)==='monthly'?'/模拟月':'')}</button>${offer.file&&record.claimed?`<a href="${offer.file}" download>另存${offer.file.endsWith('.jar')?' JAR 文件':'文件'}到电脑</a>`:''}</article>`;}
function phoneSmsMarkup(){const rows=smsView==='sent'?phoneState.sent.slice().reverse():phoneSmsRows();if(smsView==='compose')return `<section class="sms-native"><div class="sms-folder-title">✎ 编写短信 <span>简体中文</span></div><div class="sms-compose"><label>收件人<input aria-label="短信收件人" value="106XXXX" readonly></label><label class="sms-compose-body">短信内容<textarea id="phone-sms-text" maxlength="160" placeholder="编辑：漫画01 / 软件01 / 游戏01">${escapeHTML(phoneState.draft)}</textarea></label><div class="sms-writing-status"><span data-sms-counter>${phoneState.draft.length}/160</span><span>Abc　▰</span></div><button data-sms-send class="sms-send-button" ${smsSending?'disabled':''}>${smsSending?'正在发送…':'发送'}</button><button data-sms-view="inbox">取消，返回收件箱</button></div><p class="sms-local-note">本机模拟，不发送真实短信，不订阅、不收费。</p></section>`;
if(smsView==='message'&&rows.length){const record=rows[Math.min(smsSelected,rows.length-1)],offer=smsOfferFor(record.text);return `<section class="sms-native"><div class="sms-folder-title">✉ 收到的短信 <button data-sms-view="inbox">‹ 信箱</button></div><div class="sms-message-meta"><b>${record.system?'10086 · 旧日移动':'106XXXX · 旧日下载站'}</b><span>${escapeHTML(record.stamp||date+' 20:04')}</span></div><article class="sms-message-paper"><p>${escapeHTML(record.reply)}</p>${offer&&!record.system?smsDownloadCard(offer,record):''}${record.system?'<button data-desk-open="wallet">查看话费 / 梦网业务</button>':''}</article>${!record.system?'<details class="sms-delivery-receipt">':'<details hidden>'}<summary>✓ 已送达 · 查看发出的短信</summary><p>${escapeHTML(record.text)}</p><small>发送至 106XXXX · 本机模拟回执</small></details><button class="sms-reply-button" data-sms-view="compose">回复 / 再写一条</button></section>`;}
return `<section class="sms-native"><div class="sms-folder-title">✉ 信息 <span>${rows.length} 条信息</span></div><button class="sms-new-message" data-sms-view="compose">✎ 编写新信息 <span>›</span></button>${phoneState.draft?'<button class="sms-draft-row" data-sms-view="compose">▤ 草稿箱 (1)　继续编辑 ›</button>':''}<nav class="sms-folder-tabs"><button data-sms-view="inbox" aria-pressed="${smsView!=='sent'}">收件箱</button><button data-sms-view="sent" aria-pressed="${smsView==='sent'}">已发送</button></nav>${rows.map((r,i)=>`<button class="sms-inbox-row" data-sms-message="${i}"><i>${smsView==='sent'?'↗':'✉'}</i><span><b>${smsView==='sent'?'发送至 106XXXX':r.system?'10086 · 旧日移动':'106XXXX · 旧日下载站'}</b><small>${escapeHTML(smsView==='sent'?r.text:r.reply)}</small></span><em>${escapeHTML((r.stamp||'20:04').slice(-5))}</em></button>`).join('')||'<div class="sms-empty-letter"><b>✉</b><p>还没有新信息</p><span>去广告页挑个代码，<br>给旧日下载站发一条短信。</span><button data-desk-open="ads">翻翻短信下载广告</button></div>'}<div class="sms-service-tip"><b>旧日下载站</b><p>编辑 漫画01 / 铃声01 / 壁纸01<br>发送到 106XXXX，收到你的下载卡。</p></div><p class="sms-local-note">本机模拟信箱，不连接真实短信服务。</p></section>`;}
function claimSmsDownload(code){if(isTextOnlyPhone())return false;const offer=smsOfferFor(code),record=phoneState.sent.slice().reverse()[smsSelected];if(!offer||!record||record.claimed||smsOfferFor(record.text)!==offer)return false;const purchase=walletPurchase(code,smsPlanFor(record.text));if(!purchase.ok){toast(purchase.reason);const card=document.querySelector('.sms-download-card');if(card){let status=card.querySelector('[data-download-feedback]');if(!status){status=document.createElement('p');status.setAttribute('data-download-feedback','');status.setAttribute('role','status');card.appendChild(status);}status.textContent=purchase.reason;}return false;}if(offer.wallpaper)phoneState.wallpaperImage=offer.wallpaper;if(offer.app==='music'){const track=memoryTracks.findIndex(t=>t.id==='gran-vals');if(track>=0)memoryTrack=track;}installSystemApp(offer.app);record.claimed=true;savePhone();return true;}
function syncPhoneSmsSoftkeys(){if(phoneState.app!=='sms')return;document.querySelectorAll('[data-phone-soft]').forEach(b=>b.textContent=b.dataset.phoneSoft==='left'?(smsView==='compose'?'发送':'写信息'):(smsView==='inbox'?'返回':'信箱'));}
function sendSmsFromComposer(){if(smsSending)return;const text=document.querySelector('#phone-sms-text')?.value||phoneState.draft;if(!text.trim()){toast('先写一点内容吧');return;}smsSending=true;phoneState.draft=text;refreshPhone();setTimeout(()=>{smsSending=false;deliverPhoneSms(text);if(phoneSurfaceActive()&&phoneState.app==='sms')refreshPhone();toast('已收到一条短信 · 本机模拟');},650);}
function phoneComicsMarkup(){const r=kioskReads.find(r=>r.id===deskStory)||kioskReads.find(r=>r.comic),pages=kioskReadPages(r);deskComicPage=Math.max(0,Math.min(deskComicPage,pages.length-1));return `<section class="phone-comic-room"><div class="phone-wap-title">漫画与图文 · 原创夜读</div><details class="comic-shelf"><summary>换篇故事 / 目录</summary><nav>${kioskReads.map(r=>`<button data-desk-story="${r.id}" aria-pressed="${r.id===deskStory}">${escapeHTML(r.title)}</button>`).join('')}</nav></details><article><small>${r.comic?'四页短篇漫画':'原创图文故事'} · ${deskComicPage+1}/${pages.length}</small><h2>${escapeHTML(r.title)}</h2>${r.comic?`<div class="kiosk-comic-page" role="img" aria-label="雨停以前漫画第${deskComicPage+1}页" style="background-position:${deskComicPage%2?'100%':'0'} ${deskComicPage>=2?'100%':'0'}"></div>`:`<img class="comic-story-image" src="${r.image}" alt="${escapeHTML(r.title)}原创配图">`}${pages[deskComicPage].map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</article><div class="comic-page-buttons"><button data-desk-comic-page="-1" ${deskComicPage===0?'disabled':''}>‹ 上页 / 4</button><span>${deskComicPage+1}/${pages.length}</span><button data-desk-comic-page="1" ${deskComicPage===pages.length-1?'disabled':''}>下页 / 6 ›</button></div><small class="sms-local-note">本站原创作品，非历史刊物原文。</small></section>`;}
function phoneCommunityMarkup(){const c=currentCommunity();if(!c)return '<p>这个年份还没有整理社区内容。</p>';const index=communityThread,key=c.id+'-'+index;return `<section class="phone-forum"><header><small>${year()} / BBS</small><h2>${escapeHTML(c.name)}</h2><p>${escapeHTML(c.intro)}</p></header><nav>${communityAvailable().map(x=>`<button data-desk-community="${x.id}" aria-pressed="${c.id===x.id}">${escapeHTML(x.name)}</button>`).join('')}</nav>${index===null?`<div class="forum-notice">公告：进来坐坐，发言留在本机。</div>${c.topics.map((title,i)=>`<button class="forum-topic" data-phone-forum-thread="${i}"><small>${c.boards[i]}　原创体验帖</small><b>${escapeHTML(title)}</b><span>楼主：晚风　│　${(communityReplies[c.id+'-'+i]||[]).length} 条本机回复 ›</span></button>`).join('')}`:`<button class="forum-back" data-phone-forum-back>‹ 返回版面</button><article class="forum-post"><small>1楼 / 楼主：晚风</small><h3>${escapeHTML(c.topics[index])}</h3>${communityBody(c,index).map(p=>`<p>${escapeHTML(p)}</p>`).join('')}</article>${(communityReplies[key]||[]).map((p,i)=>`<article class="forum-post"><small>${i+2}楼 / 我 · 本机留言</small><p>${escapeHTML(p)}</p></article>`).join('')}<form data-phone-forum-reply><label>留一句话<textarea name="reply" maxlength="500" aria-label="手机社区本机留言" required></textarea></label><button>发表本机回复</button></form>`}<footer>原创怀旧社区 · 非历史原帖 · 留言仅本机可见</footer></section>`;}
function ucWebsiteDirectory(){return `<div class="uc-heading">旧日网址导航 <small>按 ${year()} 年筛选</small></div>${siteCatalog.map(c=>{const sites=c.sites.filter(s=>s.since<=Number(year()));return sites.length?`<details class="uc-directory-group" ${c.id==='portal'?'open':''}><summary>${escapeHTML(c.title)} · ${sites.length}</summary><div>${sites.map(s=>`<button data-desk-site="${s.url}">${escapeHTML(s.name)}</button>`).join('')}</div></details>`:'';}).join('')}`;}
function phoneWebsiteMarkup(){if(!deskWebsite)return ucWebsiteDirectory();const s=deskWebsite;return `<section class="phone-retro-site"><div class="retro-site-address">${escapeHTML(s.url)} / ${year()}</div><header><b>${escapeHTML(s.name)}</b><span>WAP 导航 · 旧日重制</span></header><div class="retro-site-ticker">小屏幕，大世界。欢迎回来！</div><nav>${[['news','新闻'],['books','小说'],['comics','漫画'],['community','论坛'],['games','游戏'],['music','音乐'],['ads','下载'],['videos','视频']].map(([id,t])=>`<button data-uc-open="${id}">${t}</button>`).join('')}</nav><h3>今日推荐 / ${year()}</h3>${(yearEvents[year()]||[]).slice(0,4).map((r,i)=>`<button class="retro-site-news" data-uc-news="${i}">· ${escapeHTML(r[1])} ›</button>`).join('')}<button class="retro-site-download" data-uc-open="ads">彩铃 / 壁纸 / Java游戏 · 短信下载 ›</button><img src="images/posters/magazine.jpg" alt="原创手机DIY广告海报"><p>本站按老式 WAP 导航形式重制，不是该站真实历史页面。</p><a href="https://web.archive.org/web/${year()}*/http://${s.url}/" target="_blank" rel="noopener noreferrer">查找该网站的当年存档 ↗</a></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-desk-open],[data-desk-section],[data-sms-offer],[data-sms-view],[data-sms-message],[data-sms-send],[data-sms-claim],[data-desk-story],[data-desk-comic-page],[data-desk-community],[data-desk-site],[data-phone-forum-thread],[data-phone-forum-back]');if(!b)return;e.preventDefault();if(b.dataset.deskOpen)return deskOpen(b.dataset.deskOpen);if(b.dataset.deskSection)return document.querySelector('#desk-'+b.dataset.deskSection)?.scrollIntoView?.({block:'start',behavior:'smooth'});if(b.dataset.smsOffer){const o=smsOfferFor(b.dataset.smsOffer);if(!o)return;smsView='compose';phoneState.draft=o.code+(smsPlanFor(b.dataset.smsOffer)==='monthly'&&o.monthly?'包月':'');return openPhoneLab('sms');}if(b.dataset.smsView){smsView=b.dataset.smsView;return refreshPhone();}if(b.dataset.smsMessage!==undefined){smsView='message';smsSelected=Number(b.dataset.smsMessage);const message=phoneSmsRows()[smsSelected];if(message?.system)markWalletMessageRead(message.id);return refreshPhone();}if(b.hasAttribute('data-sms-send'))return sendSmsFromComposer();if(b.dataset.smsClaim){if(!claimSmsDownload(b.dataset.smsClaim))return;const view=document.querySelector('#device-viewport'),scroll=view?.scrollTop||0;refreshPhone();if(view)view.scrollTop=scroll;toast('已下载到手机桌面');return;}if(b.dataset.deskStory){if(!kioskReads.some(r=>r.id===b.dataset.deskStory))return;deskStory=b.dataset.deskStory;deskComicPage=0;return deskOpen('comics');}if(b.dataset.deskComicPage){deskComicPage+=Number(b.dataset.deskComicPage);const story=kioskReads.find(r=>r.id===deskStory);if(story?.comic&&deskComicPage>=story.pages.length-1)unlockDeskStamp('comic');return refreshPhone();}if(b.dataset.deskCommunity){if(!communityAvailable().some(c=>c.id===b.dataset.deskCommunity))return;communityId=b.dataset.deskCommunity;communityThread=null;return deskOpen('community');}if(b.dataset.deskSite){const site=siteCatalog.flatMap(c=>c.sites).find(s=>s.url===b.dataset.deskSite&&s.since<=Number(year()));if(!site)return;deskWebsite=site;ucContent='web';ucQuery='';return deskOpen('browser');}if(b.hasAttribute('data-phone-forum-back')){communityThread=null;return refreshPhone();}if(b.dataset.phoneForumThread!==undefined){const i=Number(b.dataset.phoneForumThread);if(i>=0&&i<3){communityThread=i;refreshPhone();}}});
document.addEventListener('input',e=>{if(e.target.id==='phone-sms-text'){phoneState.draft=e.target.value.slice(0,160);savePhone();const count=document.querySelector('[data-sms-counter]');if(count)count.textContent=phoneState.draft.length+'/160';}if(e.target.matches('[data-desk-site-search]')){const query=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-desk-site]').forEach(b=>{if(!b.dataset.siteSearch)return;b.hidden=!b.dataset.siteSearch.toLowerCase().includes(query);if(!b.hidden)count++;});document.querySelectorAll('.desk-site-group').forEach(d=>{d.hidden=!Array.from(d.querySelectorAll('[data-site-search]')).some(b=>!b.hidden);if(query)d.open=!d.hidden;});const empty=document.querySelector('.desk-sites-empty');if(empty)empty.hidden=count>0;}});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-phone-forum-reply]'))return;e.preventDefault();const text=String(new FormData(e.target).get('reply')||'').trim().slice(0,500),c=currentCommunity();if(!text||!c||communityThread===null)return;const key=c.id+'-'+communityThread;communityReplies[key]=[...(communityReplies[key]||[]),text].slice(-20);try{localStorage.setItem('archaeo-community-replies',JSON.stringify(communityReplies));}catch{}refreshPhone();document.querySelector('[data-phone-forum-reply]')?.scrollIntoView?.({block:'end'});});
